import {inferFlowRelationshipKind,relationshipEndpoint,saveStoredGraph,storedGraph,type DocumentaryRelationshipRecord,type FlowEndpointReference,type FlowRelationshipInput} from "../data-layer-flow-graph.js";
import {transactProject} from "../utilities/data-layer/schemas.js";
import type {ProjectState,IdFactory} from "../utilities/data-layer/schemas.js";

export function saveGraphRelationship(state:ProjectState,flowId:string,fromOccurrenceId:string,input:FlowRelationshipInput,id:IdFactory):ProjectState{const graph=storedGraph(state.project,flowId),frameIds=new Set(graph.pageFrames.map(({id})=>id)),endpoint=(endpointId:string):FlowEndpointReference|undefined=>frameIds.has(endpointId)?{kind:"page-frame",id:endpointId}:undefined,sourceEndpoint=endpoint(fromOccurrenceId),targetEndpoint=endpoint(input.toStepId);if(fromOccurrenceId===input.toStepId)return state;if(!state.project.collections.flows.some(({id})=>id===flowId)||!sourceEndpoint||!targetEndpoint)throw new Error("A Flow relationship requires existing source and target Page frames.");const kind=inferFlowRelationshipKind(input.sourcePort,input.targetPort);if(!kind)return state;return transactProject(state,`Save Flow relationship ${input.id??"new"}`,(project)=>{const current=storedGraph(project,flowId),relationship:DocumentaryRelationshipRecord={id:input.id??id("flow-relationship"),sourceEndpoint,targetEndpoint,sourcePort:input.sourcePort,targetPort:input.targetPort,kind,...(input.group?{group:input.group}:{}),...(input.label?{label:input.label}:{}),...(input.documentationCondition?{documentationCondition:input.documentationCondition}:{}),...(input.expectation?{expectation:input.expectation}:{})};return saveStoredGraph(project,flowId,{...current,relationships:current.relationships.some(({id})=>id===relationship.id)?current.relationships.map((candidate)=>candidate.id===relationship.id?relationship:candidate):[...current.relationships,relationship]});});}
export function removeFlowRelationship(state:ProjectState,flowId:string,relationshipId:string):ProjectState{if(!storedGraph(state.project,flowId).relationships.some(({id})=>id===relationshipId))return state;return transactProject(state,`Delete Flow relationship ${relationshipId}`,(project)=>{const current=storedGraph(project,flowId);return saveStoredGraph(project,flowId,{...current,relationships:current.relationships.filter(({id})=>id!==relationshipId)});});}
